import{_ as a,o,c as t,a4 as s}from"./chunks/framework.DA9C4Pbl.js";const u=JSON.parse('{"title":"Updates of Arcsecond.local","description":"","frontmatter":{"title":"Updates of Arcsecond.local","visibility":"public","audience":"operator","tier":"guide","source":"handwritten"},"headers":[],"relativePath":"guides/operating/updates.md","filePath":"guides/operating/updates.md"}'),i={name:"guides/operating/updates.md"};function n(d,e,r,c,l,h){return o(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="updates-of-arcsecond-local" tabindex="-1">Updates of Arcsecond.local <a class="header-anchor" href="#updates-of-arcsecond-local" aria-label="Permalink to “Updates of Arcsecond.local”">​</a></h1><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>As of now, the installation of Arcsecond.local requires an individual authentication token, provided manually by Arcsecond. In the future, the process will be streamlined and easier.</p></div><p>Your installation can keep running while it updates: there is no need to stop it first. Two commands, from any folder once <code>arcsecond setup</code> has run on this machine:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pip3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --upgrade</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> arcsecond</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">arcsecond</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span></span></code></pre></div><p>The first updates the <code>arcsecond</code> tool itself. The second updates the installation: it brings <code>docker-compose.yml</code> up to date (see below), downloads the latest images, recreates the containers whose image changed, waits for the backend to be ready again, and prints the address. Expect a minute or two while the containers come back; the tool waits for you.</p><p><code>arcsecond status</code> says whether an installation is current: it compares the version of your <code>docker-compose.yml</code> with the one the installed tool carries, and tells you to run <code>arcsecond update</code> when they differ.</p><h2 id="why-the-compose-file-is-refreshed" tabindex="-1">Why the compose file is refreshed <a class="header-anchor" href="#why-the-compose-file-is-refreshed" aria-label="Permalink to “Why the compose file is refreshed”">​</a></h2><p>The <code>docker-compose.yml</code> file is not part of the Docker images: it is written by the <code>arcsecond</code> tool, and evolves with it — which is why the tool is updated first. <code>arcsecond update</code> rewrites the file in place when it has not been edited by hand. If it has, the file is left alone and the packaged version is written beside it as <code>docker-compose.latest.yml</code>, for you to compare and merge. Your <code>.env</code> file only gains keys it lacks, and your data is never touched.</p><p>The latest change of this kind: since CLI 3.20.0 (template version 6.4), the database and Redis containers no longer publish a port on the machine, not even on <code>localhost</code>. They are reachable from the other containers only, which is all Arcsecond ever needed, and an installation can now start next to a PostgreSQL already running on the machine. An installation that fails with <em>ports are not available</em> on <code>arcsecond start</code> is one that has not had this update; see <a href="/guides/operating/troubleshooting">Troubleshooting</a>.</p><h2 id="coming-from-a-tool-older-than-4-0" tabindex="-1">Coming from a tool older than 4.0 <a class="header-anchor" href="#coming-from-a-tool-older-than-4-0" aria-label="Permalink to “Coming from a tool older than 4.0”">​</a></h2><p>Version 4.0 of the tool changed how an installation is operated — <code>arcsecond start</code> and friends replace the <code>docker compose</code> commands these pages used to ask for. The installation itself needs no change. See <a href="/guides/operating/upgrading-to-4">Upgrading to 4.0</a>.</p>`,11)])])}const f=a(i,[["render",n]]);export{u as __pageData,f as default};
